"""Local web UI for viewing and refreshing reports."""
from __future__ import annotations
import json
from datetime import datetime
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse
from .cli import run
from .core import CN

ROOT = Path(__file__).resolve().parents[1]
REPORTS = ROOT / "reports"
PAGE = r"""<!doctype html><html lang='zh-CN'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Tripo AI 舆情日报</title><style>
:root{--ink:#172033;--muted:#667085;--blue:#2457d6;--purple:#7138b6;--cyan:#087f8c}*{box-sizing:border-box}body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;color:var(--ink);background:#f3f6fb}.shell{max-width:1240px;margin:auto;padding:24px}.hero{padding:30px 34px;border-radius:18px;color:white;background:linear-gradient(115deg,#123f91,#633cb2 60%,#078392);box-shadow:0 12px 30px #1e3a5f2b}.hero h1{margin:0 0 9px;font-size:31px;letter-spacing:.02em}.hero p{margin:0;color:#e8efff;font-size:15px}.toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:22px}.btn{border:0;border-radius:9px;padding:10px 15px;font-weight:700;cursor:pointer}.primary{background:white;color:#174ea6}.secondary{background:#ffffff24;color:white}.grid{display:grid;grid-template-columns:240px minmax(0,1fr);gap:20px;margin-top:20px}.panel,.report{background:white;border:1px solid #dde5f0;border-radius:16px;box-shadow:0 6px 20px #3341550c}.panel{padding:18px;height:max-content}.panel h2{margin:0 0 12px;font-size:16px;color:#28364d}.source{padding:11px;border-radius:9px;background:#eaf2ff;margin:8px 0;font-size:12px;line-height:1.55}.source:nth-of-type(2){background:#f3ecff}.source:nth-of-type(3){background:#e6f8f4}.source b{display:block;color:#174ea6;font-size:14px;margin-bottom:2px}.history button{width:100%;text-align:left;background:#f4efff;color:#4c1d95;margin:5px 0;font-size:12px}.report{padding:32px 38px;min-height:650px}.report .daily-report>h1{font-size:27px;line-height:1.35;color:#103b77;border-bottom:4px solid #77a9ed;padding-bottom:16px;margin:0 0 18px}.report h2{font-size:21px;color:#6533a0;background:linear-gradient(90deg,#f1eaff,#faf8ff);border-left:6px solid #8b5cf6;padding:12px 15px;margin:34px 0 16px;border-radius:0 10px 10px 0}.report h2:nth-of-type(2n){color:#086d78;background:linear-gradient(90deg,#e7fafa,#f8ffff);border-left-color:#18a8bd}.report h3{font-size:17px;line-height:1.45;color:#174b87;background:#edf4ff;border:1px solid #dae8fc;padding:11px 14px;border-radius:10px;margin:20px 0 10px}.report h4{font-size:16px;line-height:1.45;color:#6941c6;background:#faf7ff;border-left:4px solid #9b7be7;padding:10px 13px;border-radius:7px;margin:18px 0 9px}.report p{font-size:14px;line-height:1.75;color:#536176;margin:7px 0}.report a{color:#175cd3;text-decoration:none;font-weight:650}.report a:hover{text-decoration:underline}.report ul{margin:9px 0 16px;padding:0;list-style:none}.report li{font-size:14px;line-height:1.72;padding:9px 13px;margin:7px 0;background:#fafbfd;border-left:4px solid #b8ccea;border-radius:6px;color:#37465c}.report li .field{display:inline-block;color:#6941c6;font-weight:750;margin-right:5px}.report li.summary-cn{background:#fff8e8;border-left-color:#f2a900;color:#553b0a}.report li.summary-en{background:#edf9f7;border-left-color:#16a394;color:#24534f}.report li.impact{background:#f2efff;border-left-color:#7c5ce0}.meta{display:flex;gap:10px;flex-wrap:wrap;color:#e5edff;font-size:13px}.badge{display:inline-block;padding:4px 9px;border-radius:999px;background:#dcfce7;color:#166534}.empty{padding:50px;text-align:center;color:var(--muted)}@media(max-width:800px){.shell{padding:12px}.grid{grid-template-columns:1fr}.report{padding:21px}.hero{padding:24px}.hero h1{font-size:24px}.report .daily-report>h1{font-size:22px}.report h2{font-size:19px}}
</style><body><div class='shell'><section class='hero'><h1>Tripo AI 舆情与行业日报</h1><p>面向 VAST / Tripo AI 的 AI 3D、竞品与行业政策情报中心</p><div class='toolbar'><button class='btn primary' id='b' onclick='refresh()'>刷新日报</button><button class='btn secondary' onclick='load()'>重新加载</button><button class='btn secondary' onclick="location.href='/api/export.xlsx'">导出当日 Excel</button><span id='s' class='meta'>正在读取...</span></div></section><div class='grid'><aside class='panel'><h2>来源概览</h2><div class='source'><b id='source-count'>已配置 28 个公开来源</b><span id='source-detail'>正在检查本次可用来源…</span></div><div class='source'><b>覆盖方向</b>AI 3D · 世界模型 · 机器人 · 政策 · 芯片</div><div class='source'><b>数据原则</b>原始链接、时间窗口、失败来源透明标记</div><h2 style='margin-top:25px'>历史日报</h2><div id='history' class='history'></div></aside><main class='report' id='report'><div class='empty'>正在加载日报...</div></main></div></div><script>
const KEY='tripo-report-history-v1';function esc(s){return s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}function decorate(root){root.querySelectorAll('li').forEach(li=>{let t=li.textContent||'';let m=t.match(/^([^：]{2,24}：)/);if(m){let html=li.innerHTML;li.innerHTML=`<span class="field">${esc(m[1])}</span>`+html.slice(m[1].length)}if(t.startsWith('中文报道概述：'))li.classList.add('summary-cn');if(t.startsWith('English summary:'))li.classList.add('summary-en');if(t.startsWith('对 Tripo/VAST 的影响'))li.classList.add('impact');if(t.startsWith('话题数据：')){li.style.background='#eaf2ff';li.style.borderLeftColor='#3478d4'}})}function save(day,html){let a=JSON.parse(localStorage.getItem(KEY)||'[]').filter(x=>x.day!==day);a.unshift({day,html,time:new Date().toLocaleString()});localStorage.setItem(KEY,JSON.stringify(a.slice(0,30)));drawHistory()}function drawHistory(){let a=JSON.parse(localStorage.getItem(KEY)||'[]');history.innerHTML=a.length?a.map((x,i)=>`<button class='btn' onclick='showHistory(${i})'>${esc(x.day)}<small style='display:block;color:#64748b'>${esc(x.time)}</small></button>`).join(''):'<div style="color:#94a3b8;font-size:13px">刷新后自动保存历史</div>'}function showHistory(i){let a=JSON.parse(localStorage.getItem(KEY)||'[]');if(a[i]){report.innerHTML=a[i].html;decorate(report)}s.textContent='已查看历史日报：'+a[i].day}async function load(){try{let d=await (await fetch('/api/status')).json();s.innerHTML=`<span class='badge'>${esc(d.message)}</span>`;if(d.sources){document.getElementById('source-count').textContent=`已配置 ${d.sources.configured} 个公开来源`;document.getElementById('source-detail').textContent=`本次成功 ${d.sources.ok} 个，失败 ${d.sources.failed} 个`}let h=await (await fetch((d.url||'/api/report')+'?t='+Date.now(),{cache:'no-store'})).text();report.innerHTML=h;decorate(report);save(d.message.replace('最新日报：',''),h)}catch(e){s.textContent='加载失败：'+e}}async function refresh(){b.disabled=true;b.textContent='采集中...';s.textContent='正在访问公开来源并生成日报';try{let d=await (await fetch('/api/refresh',{method:'POST'})).json();if(!d.html)throw new Error(d.message||'生成失败');s.textContent=d.message;report.innerHTML=d.html;decorate(report);if(d.sources){document.getElementById('source-count').textContent=`已配置 ${d.sources.configured} 个公开来源`;document.getElementById('source-detail').textContent=`本次成功 ${d.sources.ok} 个，失败 ${d.sources.failed} 个`}save(d.day,d.html)}catch(e){s.textContent='刷新失败：'+e}finally{b.disabled=false;b.textContent='刷新日报'}}drawHistory();load();</script></body></html>"""
def latest():
    x=sorted(REPORTS.glob('*.html'),reverse=True); return x[0] if x else None
class Handler(BaseHTTPRequestHandler):
    def log_message(self,*a): pass
    def out(self,obj,code=200):
        b=json.dumps(obj,ensure_ascii=False).encode(); self.send_response(code); self.send_header('Content-Type','application/json; charset=utf-8'); self.send_header('Content-Length',str(len(b))); self.end_headers(); self.wfile.write(b)
    def do_GET(self):
        p=urlparse(self.path).path
        if p=='/':
            b=PAGE.encode(); self.send_response(200); self.send_header('Content-Type','text/html; charset=utf-8'); self.send_header('Content-Length',str(len(b))); self.end_headers(); self.wfile.write(b); return
        if p=='/api/status':
            f=latest(); self.out({'url':'/reports/'+f.name if f else None,'message':f'最新日报：{f.stem}' if f else '暂无日报，请点击刷新'}); return
        if p.startswith('/reports/'):
            f=REPORTS/Path(p.removeprefix('/reports/')).name
            if f.exists() and f.suffix=='.html':
                b=f.read_bytes(); self.send_response(200); self.send_header('Content-Type','text/html; charset=utf-8'); self.send_header('Content-Length',str(len(b))); self.end_headers(); self.wfile.write(b); return
        self.send_error(404)
    def do_POST(self):
        if urlparse(self.path).path!='/api/refresh': self.send_error(404); return
        day=datetime.now(CN).date().isoformat(); rc=run(day); self.out({'ok':rc==0,'message':'刷新完成' if rc==0 else '刷新完成，但部分来源失败；请查看日报顶部状态'})
def main():
    import argparse, os
    p=argparse.ArgumentParser(); p.add_argument('--host',default=os.getenv('HOST','127.0.0.1')); p.add_argument('--port',type=int,default=int(os.getenv('PORT','8765'))); a=p.parse_args(); print(f'网页地址：http://{a.host}:{a.port}'); ThreadingHTTPServer((a.host,a.port),Handler).serve_forever()
if __name__=='__main__': main()
